	set := map[string]bool{}
	for _, p := range raw.Files {
		if strings.TrimSpace(p) != "" {
			set[p] = true
		}
	}
	for _, t := range raw.Tasks {
		for _, e := range t.Evidence {
			if strings.TrimSpace(e.Path) != "" {
				set[e.Path] = true
			}
		}
	}
	var out []string
	for p := range set {
