	"github.com/Antonio7098/ultraplan-go/internal/platform/gitpublish"
)

const StageSmoke PlanningStage = "smoke"

const SmokeProtocolMajor = 1

type SmokeExecutionStatus string
type SmokeVerdict string
type SmokePhase string

const (
	SmokeReady     SmokeExecutionStatus = "ready"
	SmokeRunning   SmokeExecutionStatus = "running"
	SmokeCompleted SmokeExecutionStatus = "completed"
	SmokeFailed    SmokeExecutionStatus = "failed"
	SmokeCancelled SmokeExecutionStatus = "cancelled"

	SmokePass               SmokeVerdict = "pass"
	SmokePassWithOpenIssues SmokeVerdict = "pass_with_open_issues"
	SmokeFailVerdict        SmokeVerdict = "fail"
	SmokeBlockedVerdict     SmokeVerdict = "blocked"
	SmokeNotApplicable      SmokeVerdict = "not_applicable"

	SmokePhasePreflight          SmokePhase = "preflight"
	SmokePhaseAuthoring          SmokePhase = "authoring"
	SmokePhaseDiscovery          SmokePhase = "discovery"
	SmokePhaseSelection          SmokePhase = "selection"
	SmokePhaseRunning            SmokePhase = "running"
	SmokePhaseValidatingEvidence SmokePhase = "validating_evidence"
	SmokePhaseWritingArtifact    SmokePhase = "writing_artifact"
	SmokePhaseCompleted          SmokePhase = "completed"
	SmokePhaseCancelled          SmokePhase = "cancelled"
	SmokePhaseFailed             SmokePhase = "failed"
)

type SmokeSettings struct {
	DiscoveryTimeout, RunTimeout, CleanupGrace time.Duration
	StdoutLimit, StderrLimit                   int
	Environment                                []string
	Sources                                    map[string]string
	Getenv                                     func(string) string
}

func DefaultSmokeSettings() SmokeSettings {
	return SmokeSettings{DiscoveryTimeout: 30 * time.Second, RunTimeout: 30 * time.Minute, CleanupGrace: 5 * time.Second, StdoutLimit: 4 << 20, StderrLimit: 1 << 20, Environment: []string{"PATH", "HOME", "TMPDIR", "LANG", "LC_ALL"}, Sources: map[string]string{}, Getenv: os.Getenv}
}

type SmokeRequest struct {
	Level, Suite, Test string
	Timeout            time.Duration
	ForceReview        bool
	OverrideConfirmed  bool
	OverrideRationale  string
	DryRun             bool
	NonInteractive     bool
	Progress           func(SmokeProgress)
}

type SmokeProgress struct {
	Phase         SmokePhase `json:"phase"`
	Suite         string     `json:"suite,omitempty"`
	Test          string     `json:"test,omitempty"`
	Message       string     `json:"message,omitempty"`
	Completed     int        `json:"completed,omitempty"`
	Total         int        `json:"total,omitempty"`
	DroppedEvents int        `json:"dropped_events,omitempty"`
}

type SmokeCounts struct {
	Total   int `json:"total"`
	Passed  int `json:"passed"`
	Failed  int `json:"failed"`
	Skipped int `json:"skipped"`
	Errors  int `json:"errors"`
}

type SmokeEvidence struct {
	Kind       string    `json:"kind"`
	Path       string    `json:"path"`
	SHA256     string    `json:"sha256"`
	Size       int64     `json:"size"`
	ModifiedAt time.Time `json:"modified_at"`
}

type SmokeIssue struct {
	ID       string `json:"id"`
	Status   string `json:"status"`
	Path     string `json:"path"`
	TestID   string `json:"test_id,omitempty"`
	Severity string `json:"severity,omitempty"`
	Title    string `json:"title,omitempty"`
	Summary  string `json:"summary,omitempty"`
	Theory   string `json:"theory,omitempty"`
	Evidence string `json:"evidence,omitempty"`
	Action   string `json:"action,omitempty"`
}

type SmokeTestResult struct {
	ID       string `json:"id"`
	Status   string `json:"status"`
	Summary  string `json:"summary,omitempty"`
	Theory   string `json:"theory,omitempty"`
	Evidence string `json:"evidence,omitempty"`
}

type SmokeCoverageTest struct {
	ID       string   `json:"id"`
	Suite    string   `json:"suite"`
	Coverage []string `json:"coverage"`
}

type SmokeCoverageRequirement struct {
	ID          string   `json:"id"`
	Description string   `json:"description,omitempty"`
	MappedTests []string `json:"mapped_tests"`
}

type SmokeCoverageMatrixRow struct {
	TestID string `json:"test_id"`
	Suite  string `json:"suite"`
	Cells  []bool `json:"cells"`
}

type SmokeCoverageMapping struct {
	Sprint           string                     `json:"sprint"`
	Suites           []string                   `json:"suites"`
	Complete         bool                       `json:"complete"`
	NotApplicable    bool                       `json:"not_applicable,omitempty"`
	Rationale        string                     `json:"rationale,omitempty"`
	RequiredCoverage []string                   `json:"required_coverage"`
	Requirements     []SmokeCoverageRequirement `json:"requirements,omitempty"`
	Tests            []SmokeCoverageTest        `json:"tests"`
	Matrix           []SmokeCoverageMatrixRow   `json:"matrix,omitempty"`
}

func (m *SmokeCoverageMapping) EnsureMatrix() {
	if m == nil {
		return
	}
	m.Matrix = make([]SmokeCoverageMatrixRow, 0, len(m.Tests))
	for _, test := range m.Tests {
		covered := map[string]bool{}
		for _, id := range test.Coverage {
			covered[id] = true
		}
		row := SmokeCoverageMatrixRow{TestID: test.ID, Suite: test.Suite, Cells: make([]bool, len(m.Requirements))}
		for i, requirement := range m.Requirements {
			row.Cells[i] = covered[requirement.ID]
		}
		m.Matrix = append(m.Matrix, row)
	}
}

type SmokeResult struct {
	Project            string                `json:"project"`
	Sprint             string                `json:"sprint"`
	Harness            string                `json:"harness"`
	Protocol           string                `json:"protocol"`
	Artifact           string                `json:"artifact"`
	Status             SmokeExecutionStatus  `json:"execution_status"`
	Verdict            SmokeVerdict          `json:"verdict,omitempty"`
	Ready              bool                  `json:"ready"`
	Stale              bool                  `json:"stale"`
	ReviewOverride     bool                  `json:"review_override"`
	OverrideRationale  string                `json:"override_rationale,omitempty"`
	ReviewVerdict      ReviewVerdict         `json:"review_verdict"`
	ReviewFingerprint  string                `json:"review_fingerprint"`
	ScopeKind          string                `json:"scope_kind,omitempty"`
	Scope              string                `json:"scope,omitempty"`
	ScopeRationale     string                `json:"scope_rationale,omitempty"`
	DurationClass      string                `json:"duration_class,omitempty"`
	CostClass          string                `json:"cost_class,omitempty"`
	EvidenceRoots      []string              `json:"evidence_roots,omitempty"`
	Prerequisites      []string              `json:"prerequisites,omitempty"`
	Diagnostics        []string              `json:"diagnostics,omitempty"`
	SafeArgv           string                `json:"safe_argv,omitempty"`
	RunID              string                `json:"run_id,omitempty"`
	AuthorRunID        string                `json:"author_run_id,omitempty"`
	AuthorModel        string                `json:"author_model,omitempty"`
	AuthorChangedPaths []string              `json:"author_changed_paths,omitempty"`
	Runtime            string                `json:"runtime,omitempty"`
	Model              string                `json:"model,omitempty"`
	Duration           time.Duration         `json:"duration_ns,omitempty"`
	EffectiveTimeout   time.Duration         `json:"effective_timeout_ns,omitempty"`
	TimeoutSource      string                `json:"timeout_source,omitempty"`
	Counts             SmokeCounts           `json:"counts"`
	Evidence           []SmokeEvidence       `json:"evidence,omitempty"`
	Issues             []SmokeIssue          `json:"issues,omitempty"`
	Tests              []SmokeTestResult     `json:"tests,omitempty"`
	CoverageMapping    *SmokeCoverageMapping `json:"coverage_mapping,omitempty"`
	NextAction         string                `json:"next_action,omitempty"`
	DryRun             bool                  `json:"dry_run"`
	DiagnosticOnly     bool                  `json:"diagnostic_only"`
	Reconciliation     bool                  `json:"reconciliation_required"`
	Publications       []gitpublish.Result   `json:"publications,omitempty"`
}

type SmokeStageState struct {
	Status             SmokeExecutionStatus  `json:"status"`
	Verdict            SmokeVerdict          `json:"verdict,omitempty"`
	Path               string                `json:"path"`
	LastRunAt          *time.Time            `json:"lastRunAt,omitempty"`
	ReviewFingerprint  string                `json:"reviewFingerprint,omitempty"`
	SmokeFingerprint   string                `json:"smokeFingerprint,omitempty"`
	RunID              string                `json:"runId,omitempty"`
	AuthorRunID        string                `json:"authorRunId,omitempty"`
	AuthorModel        string                `json:"authorModel,omitempty"`
	AuthorChangedPaths []string              `json:"authorChangedPaths,omitempty"`
	CoverageMapping    *SmokeCoverageMapping `json:"coverageMapping,omitempty"`
	EvidenceID         string                `json:"evidenceId,omitempty"`
	ReviewOverride     bool                  `json:"reviewOverride"`
	Stale              bool                  `json:"stale"`
	Reconciliation     bool                  `json:"reconciliationRequired"`
	Diagnostics        []string              `json:"diagnostics,omitempty"`
	ArtifactDigest     string                `json:"artifactDigest,omitempty"`
	InputFingerprint   string                `json:"inputFingerprint,omitempty"`
	Issues             []SmokeIssue          `json:"issues,omitempty"`
	Evidence           []EvidenceReference   `json:"evidence,omitempty"`
	Override           *DiagnosticOverride   `json:"override,omitempty"`
	ActiveAttempt      *VerificationAttempt  `json:"activeAttempt,omitempty"`
	LastAttempt        *VerificationAttempt  `json:"lastAttempt,omitempty"`
	LastComplete       *SmokeCompletion      `json:"lastComplete,omitempty"`
}

type SmokeCompletion struct {
	Verdict            SmokeVerdict          `json:"verdict"`
	Artifact           string                `json:"artifact"`
	ArtifactDigest     string                `json:"artifactDigest"`
	InputFingerprint   string                `json:"inputFingerprint"`
	CompletedAt        time.Time             `json:"completedAt"`
	RunID              string                `json:"runId,omitempty"`
	AuthorRunID        string                `json:"authorRunId,omitempty"`
	AuthorModel        string                `json:"authorModel,omitempty"`
	AuthorChangedPaths []string              `json:"authorChangedPaths,omitempty"`
	CoverageMapping    *SmokeCoverageMapping `json:"coverageMapping,omitempty"`
	EvidenceID         string                `json:"evidenceId,omitempty"`
	Evidence           []EvidenceReference   `json:"evidence,omitempty"`
	Issues             []SmokeIssue          `json:"issues,omitempty"`
	Override           *DiagnosticOverride   `json:"override,omitempty"`
}

type SmokeError struct {
	Code, Category, Message, Guidance string
	Err                               error
}

func (e *SmokeError) Error() string {
	if e == nil {
		return ""
	}
	if e.Err != nil {
		return fmt.Sprintf("smoke %s: %s: %v", e.Category, e.Message, e.Err)
	}
	return fmt.Sprintf("smoke %s: %s", e.Category, e.Message)
}
func (e *SmokeError) Unwrap() error {
	if e == nil {
		return nil
	}
	return e.Err
}

func smokeError(code, category, message, guidance string, err error) error {
	return &SmokeError{Code: code, Category: category, Message: message, Guidance: guidance, Err: err}
}

func AsSmokeError(err error) (*SmokeError, bool) {
	var target *SmokeError
	ok := errors.As(err, &target)
	return target, ok
}

func validSmokeVerdict(v SmokeVerdict) bool {
	switch v {
	case SmokePass, SmokePassWithOpenIssues, SmokeFailVerdict, SmokeBlockedVerdict, SmokeNotApplicable:
		return true
	}
	return false
}

func validateSmokeStageState(root string, sp Sprint, state SmokeStageState, path string) error {
	switch state.Status {
	case SmokeReady, SmokeRunning, SmokeCompleted, SmokeFailed, SmokeCancelled:
	default:
		return fmt.Errorf("%w: %s: smoke has unsupported status %q", ErrFlowStateMalformed, path, state.Status)
	}
	if state.Verdict != "" && !validSmokeVerdict(state.Verdict) {
		return fmt.Errorf("%w: %s: smoke has unsupported verdict %q", ErrFlowStateMalformed, path, state.Verdict)
	}
	if state.Path != ArtifactRelPath(sp, StageSmoke) {
		return fmt.Errorf("%w: %s: smoke path mismatch", ErrFlowStateMalformed, path)
	}
	if _, err := resolveSprintContained(root, sp, state.Path); err != nil {
		return fmt.Errorf("%w: %s: unsafe smoke path: %v", ErrFlowStateMalformed, path, err)
	}
	for _, d := range state.Diagnostics {
		if len(d) > 240 {
			return fmt.Errorf("%w: %s: smoke diagnostic too long", ErrFlowStateMalformed, path)
		}
	}
	if err := validateAttempt(state.ActiveAttempt, true); err != nil {
		return fmt.Errorf("%w: %s: smoke active attempt: %v", ErrFlowStateMalformed, path, err)
	}
	if err := validateAttempt(state.LastAttempt, false); err != nil {
		return fmt.Errorf("%w: %s: smoke last attempt: %v", ErrFlowStateMalformed, path, err)
	}
	if state.Override != nil {
		if !state.Override.Requested || !state.Override.Confirmed || strings.TrimSpace(state.Override.Rationale) == "" || len(state.Override.Rationale) > 240 || strings.ContainsAny(state.Override.Rationale, "\x00\r\n") {
			return fmt.Errorf("%w: %s: invalid diagnostic override", ErrFlowStateMalformed, path)
		}
	}
	for _, issue := range state.Issues {
		if issue.ID == "" || (issue.Status != "open" && issue.Status != "resolved") {
			return fmt.Errorf("%w: %s: invalid smoke issue", ErrFlowStateMalformed, path)
		}
	}
	if state.LastComplete != nil {
		if state.LastComplete.Artifact != ArtifactRelPath(sp, StageSmoke) || state.LastComplete.CompletedAt.IsZero() || state.LastComplete.InputFingerprint == "" || state.LastComplete.ArtifactDigest == "" {
			return fmt.Errorf("%w: %s: invalid smoke lastComplete", ErrFlowStateMalformed, path)
		}
	}
	return nil
}

package app

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
	"github.com/Antonio7098/ultraplan-go/internal/study"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

// sharedOperationRunner is the single runtime-backed implementation used by
// terminal and browser adapters. Surface code owns presentation and
// confirmation; workflow semantics remain here and in the product services.
func sharedOperationRunner(deps dependencies, root workspace.Root, effective config.Effective, useCases dashboardUseCases) func(context.Context, OperationRequest, func(OperationEvent)) (OperationResult, error) {
	return func(ctx context.Context, req OperationRequest, emit func(OperationEvent)) (OperationResult, error) {
		result := OperationResult{State: OperationComplete, Subject: operationFirstNonEmpty(req.Project+"/"+req.Sprint, req.Study)}
		switch req.Kind {
		case OperationStage:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.FlowStage(ctx, req.Project, req.Sprint, stageFlowRequest(req, func(progress sprint.FlowProgress) {
				summary := displaySafe(progress.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Stage), Message: progress.State + ": " + summary, PhaseState: progress.State, SafeSummary: summary})
			}))
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationFlow:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			flow := stageFlowRequest(req, func(progress sprint.FlowProgress) {
				summary := displaySafe(progress.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Stage), Message: progress.State + ": " + summary, PhaseState: progress.State, SafeSummary: summary})
			})
			flow.Review = sprint.ReviewRequest{Restart: req.RestartReview}
			flow.Smoke = sprint.SmokeRequest{NonInteractive: true, OverrideConfirmed: req.ForceReview, ForceReview: req.ForceReview, OverrideRationale: req.OverrideRationale}
			r, e := runSprintFlow(ctx, service, req.Project, req.Sprint, flow)
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationExecuteStart, OperationExecuteResume:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.Execute(ctx, req.Project, req.Sprint, sprint.ExecuteRequest{TaskID: req.Task, ModelOverride: req.Model, Resume: req.Kind == OperationExecuteResume})
			result.Message = r.Message
			result = operationWithSprintFindings(result, r.Findings)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationReviewStart:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.Review(ctx, req.Project, req.Sprint, sprint.ReviewRequest{Concurrency: req.Parallelism, Focus: req.ReviewFocus, Restart: req.RestartReview, ModelOverride: req.Model, Progress: func(p sprint.ReviewProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: "review", Task: p.CoverageID, Message: p.Message, Completed: p.Completed, Total: p.Total})
			}})
			result.Message = fmt.Sprintf("%s verdict=%s", r.Status, r.Verdict)
			for _, f := range r.Findings {
				result.Findings = append(result.Findings, DisplayFinding{Severity: f.Severity, Section: "review", Problem: f.Title, Cause: f.Detail, Suggestion: f.Action})
			}
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationSmokeStart:
			service := sprint.NewService(root.Path).WithPublisher(stagePublisher(effective.Config)).WithSmokeSettings(smokeSettings(effective, envLookup(deps.env)))
			var timeout time.Duration
			if req.Timeout != "" {
				timeout, _ = time.ParseDuration(req.Timeout)
			}
			r, e := service.RunSmoke(ctx, req.Project, req.Sprint, sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, Timeout: timeout, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale, Progress: func(p sprint.SmokeProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: string(p.Phase), Task: operationFirstNonEmpty(p.Test, p.Suite), Message: p.Message, Completed: p.Completed, Total: p.Total})
			}})
			result.Message = fmt.Sprintf("%s verdict=%s run=%s next=%s", r.Status, r.Verdict, r.RunID, r.NextAction)
			if r.Artifact != "" {
				if preview, readErr := useCases.PreviewArtifact(ctx, r.Artifact); readErr == nil {
					result.Content, result.Truncated = boundContent(preview.Content)
				}
			}
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationVerifyStart:
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			var timeout time.Duration
			if req.Timeout != "" {
				timeout, _ = time.ParseDuration(req.Timeout)
			}
			r, e := service.Verify(ctx, req.Project, req.Sprint, sprint.VerifyRequest{To: sprint.PlanningStage(req.Stage), Review: sprint.ReviewRequest{Focus: req.ReviewFocus, Restart: req.RestartReview}, Smoke: sprint.SmokeRequest{Level: req.Level, Suite: req.Suite, Test: req.Test, Timeout: timeout, ForceReview: req.ForceReview, OverrideConfirmed: req.ForceReview, OverrideRationale: req.OverrideRationale}, Progress: func(p sprint.FlowProgress) {
				summary := displaySafe(p.Message)
				emit(OperationEvent{State: OperationRunning, Stage: string(p.Stage), Message: p.State + ": " + summary, PhaseState: p.State, SafeSummary: summary})
			}})
			result.Message = fmt.Sprintf("assessment=%s next=%s", r.Verification.Assessment, r.Verification.NextAction)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationQAStart, OperationQAResume:
			token, fence, e := qaOwnershipFromContext(ctx)
			if e != nil {
				return failedOperation(result, e)
			}
			service, e := sprintRuntimeService(deps, root, tuiSprintRuntimeProgress(emit))
			if e != nil {
				return failedOperation(result, e)
			}
			service = service.WithQAWriterFence(fence)
			r, e := service.RunQA(ctx, req.Project, req.Sprint, sprint.QARunRequest{Resume: req.Kind == OperationQAResume, FocusShard: req.Task, Suite: req.Suite, EvidenceProducing: req.Suite == "", WriterToken: token, Progress: func(progress sprint.QAProgress) {
				emit(OperationEvent{State: OperationRunning, Stage: string(progress.Phase), Task: progress.ShardID, Message: progress.Message, Action: progress.Event, Reason: string(progress.ShardPhase), Detail: string(progress.ShardKind), Completed: progress.Completed, Total: progress.Total})
			}})
			result.Message = fmt.Sprintf("phase=%s shards=%d/%d next=%s", r.State.Phase, r.State.CompletedShards, r.State.TotalShards, r.State.NextAction)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationStudyStart, OperationStudyResume:
			flags := runAllFlags{}
			flags.parallelism = &req.Parallelism
			flags.model = req.Model
			service, parallel, summary, e := runLoopService(deps, root, flags)
			if e != nil {
				return failedOperation(result, e)
			}
			r, e := service.RunLoop(ctx, study.RunLoopRequest{StudyRef: req.Study, DimensionRefs: req.Dimensions, SourceRefs: req.Sources, Parallelism: parallel, Model: studyModelOverride(deps, flags.model), Config: summary, Continue: req.Kind == OperationStudyResume, Command: []string{"ultraplan", "operation"}, Progress: func(p study.RunLoopProgress) {
				stats := operationTaskStats(p.Task, time.Now().UTC())
				event := OperationEvent{State: OperationRunning, Task: p.Task.ID, Stage: string(p.Event), Message: strings.TrimSpace(p.Task.DimensionRef + " " + p.Task.Source), Completed: p.ScopeCounts.Completed, Total: p.ScopeCounts.Total, Attempt: p.Task.Attempts, RuntimeAttempts: stats.RuntimeAttempts, Turns: stats.Turns, TurnsKnown: stats.TurnsKnown, Tokens: stats.Tokens, TokensKnown: stats.TokensKnown, InputTokens: stats.InputTokens, OutputTokens: stats.OutputTokens, ReasoningTokens: stats.ReasoningTokens, CacheReadTokens: stats.CacheReadTokens, CacheWriteTokens: stats.CacheWriteTokens, Duration: stats.Duration, Provider: stats.Provider, Model: stats.Model, Harness: stats.Runtime, Cost: stats.Cost, RuntimeEvents: stats.Events}
				if p.RuntimeEvent != nil {
					applyRuntimeObservation(&event, *p.RuntimeEvent)
					event.Message = runtimeProgressSummary(*p.RuntimeEvent)
				}
				emit(event)
			}})
			result.Message = string(r.Status)
			if e != nil {
				return failedOperation(result, e)
			}
		case OperationStudyCancel:
			service := study.NewService(root.Path)
			listing, e := service.ListStudy(req.Study)
			if e != nil {
				return failedOperation(result, e)
			}
			info, e := study.CancelRunLoop(listing.Study)
			if e != nil {
				return failedOperation(result, e)
			}
			result.Message = fmt.Sprintf("cancellation requested from run-loop process %d", info.PID)
		default:
			return failedOperation(result, fmt.Errorf("unsupported runtime operation %q", req.Kind))
		}
		emit(OperationEvent{State: OperationComplete, Message: "operation complete"})
		return result, nil
	}
}

// stageFlowRequest builds the sprint flow request for a stage or flow
// operation. A requested model applies to the selected target stage and, as a
// fallback for stages without dedicated per-stage handling (code-context), as
// the generic model override. Empty models keep configured defaults.
func stageFlowRequest(req OperationRequest, progress func(sprint.FlowProgress)) sprint.FlowRequest {
	flow := sprint.FlowRequest{To: sprint.PlanningStage(req.Stage), ModelOverride: req.Model}
	if req.Model != "" && req.Stage != "" {
		stage := sprint.PlanningStage(req.Stage)
		if _, ok := flow.StageOverrides[stage]; !ok {
			flow.StageOverrides = map[sprint.PlanningStage]sprint.StageRuntime{}
		}
		override := flow.StageOverrides[stage]
		override.Model = req.Model
		flow.StageOverrides[stage] = override
	}
	flow.Progress = progress
	return flow
}

