	"testing"

	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

type probeFailReviewRuntime struct{ calls int }

func (r *probeFailReviewRuntime) StartRun(_ context.Context, req pruntime.Request) (pruntime.Result, error) {
	r.calls++
	data, _ := json.Marshal(ReviewCoverageResult{
		SchemaVersion: 1,
		CoverageID:    req.Metadata["coverage"],
		Applicability: "direct",
		Summary:       "checked",
		Findings: []ReviewFinding{{
			ID:            "F-" + req.Metadata["coverage"],
			Severity:      "high",
			Applicability: "direct",
			Title:         "violation",
			Detail:        "detail",
			Action:        "fix",
			Citations:     []ReviewCitation{{Path: "projects/proj/sprints/01-alpha/requirements.md", StartLine: 1, EndLine: 1}},
		}},
	})
	return pruntime.Result{Events: []pruntime.Event{{Payload: map[string]any{"content": string(data)}}}, Permissions: pruntime.PermissionSummary{Mode: "restricted"}}, nil
}

func probeFailingReview(t *testing.T) (string, Sprint) {
	t.Helper()
	root, sp := reviewFixture(t)
	writeFileContent(t, sp.Path, `{"status":"complete","files":["internal/sprint/review.go"]}`+"\n", ".run-state.json")
	harness := t.TempDir()
	writeFileContent(t, harness, "#!/bin/sh\n", "runner")
	if err := os.Chmod(filepath.Join(harness, "runner"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(harness, "runs"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(harness, "issues"), 0o755); err != nil {
		t.Fatal(err)
	}
	manifest := `{"schemaVersion":1,"protocolVersion":"1.0","harness":{"id":"fake","version":"1"},"executable":"runner","cwd":".","commands":{"discover":["discover"],"run":["run"]},"evidence":{"runs":"runs","issues":"issues"},"authoring":{"paths":["suite"]},"capabilities":["discovery","run","evidence-v1","scope-mapping","authoring-v1"],"environment":[]}`
	writeFileContent(t, harness, manifest, "manifest.json")
	projectIndexPath := filepath.Join(root, "projects", "proj", "project-index.md")
	data, _ := os.ReadFile(projectIndexPath)
	data = append(data, []byte("\n## Smoke Harnesses\n\n| Harness | Path | Manifest | Evidence | Useful For | Status |\n|---|---|---|---|---|---|\n| fake | "+harness+" | "+filepath.Join(harness, "manifest.json")+" | runs/ and issues/ | tests | current |\n")...)
	if err := os.WriteFile(projectIndexPath, data, 0o644); err != nil {
		t.Fatal(err)
	}
	service := NewService(root).WithRuntime(&probeFailReviewRuntime{}).WithStageRuntime(map[PlanningStage]StageRuntime{StageReview: {Model: "test/model"}, StageSmoke: {Model: "test/author"}})
	result, err := service.Verify(context.Background(), "proj", "01", VerifyRequest{To: StageReview})
	if err == nil || result.ReviewResult == nil || result.ReviewResult.Verdict != ReviewFail || result.ReviewResult.Status != ReviewCompleted {
		t.Fatalf("expected completed failing review via verify: result=%+v err=%v", result, err)
	}
	state, err := LoadFlowState(root, sp)
	if err != nil || state.Review == nil || state.Review.Status != ReviewCompleted || state.Review.Verdict != ReviewFail {
		t.Fatalf("flow state=%+v err=%v", state.Review, err)
	}
	return root, sp
}

func TestProbeDiagnosticOverrideCommitsCanonicalBlockedSmoke(t *testing.T) {
	root, sp := probeFailingReview(t)
	runner := &smokeRecordingRunner{discovery: smokeDiscovery{SchemaVersion: 1, ProtocolVersion: "1.0", HarnessID: "fake", EvidenceSchema: 1}}
	author := &smokeAuthorRuntime{}
	service := NewService(root).WithRuntime(author).WithProcessRunner(runner).WithSmokeSettings(DefaultSmokeSettings()).WithStageRuntime(map[PlanningStage]StageRuntime{StageReview: {Model: "test/model"}, StageSmoke: {Model: "test/author"}})
	result, err := service.RunSmoke(context.Background(), "proj", "01", SmokeRequest{ForceReview: true, OverrideConfirmed: true, OverrideRationale: "operator diagnostic evidence"})
	t.Logf("RunSmoke err=%v status=%s verdict=%s diagnostic_only=%t artifact=%s", err, result.Status, result.Verdict, result.DiagnosticOnly, result.Artifact)
	smokePath := filepath.Join(sp.Path, "smoke.md")
	data, readErr := os.ReadFile(smokePath)
	t.Logf("smoke.md exists err=%v contains_diagnostic_true=%t", readErr, strings.Contains(string(data), "Diagnostic only: `true`"))
	state, stateErr := LoadFlowState(root, sp)
	if stateErr == nil && state.Smoke != nil {
		t.Logf("flow smoke status=%s verdict=%s override=%+v lastComplete=%v", state.Smoke.Status, state.Smoke.Verdict, state.Smoke.Override, state.Smoke.LastComplete != nil)
	}
	status, _ := service.VerificationStatus("proj", "01")
	t.Logf("verification assessment=%s next=%s smoke_fresh=%t", status.Assessment, status.NextAction, status.Smoke.Fresh)
}

func TestProbeGateBlocksWithoutForce(t *testing.T) {
	root, sp := probeFailingReview(t)
	runner := &smokeRecordingRunner{discovery: smokeDiscovery{SchemaVersion: 1, ProtocolVersion: "1.0", HarnessID: "fake", EvidenceSchema: 1}}
	author := &smokeAuthorRuntime{}
	service := NewService(root).WithRuntime(author).WithProcessRunner(runner).WithSmokeSettings(DefaultSmokeSettings()).WithStageRuntime(map[PlanningStage]StageRuntime{StageReview: {Model: "test/model"}, StageSmoke: {Model: "test/author"}})
	result, err := service.RunSmoke(context.Background(), "proj", "01", SmokeRequest{})
	t.Logf("control err=%v status=%s smoke_md_exists=%t calls=%d", err, result.Status, func() bool { _, e := os.Stat(filepath.Join(sp.Path, "smoke.md")); return e == nil }(), len(runner.calls))
}

